Lighting.ClockTime = 14
Lighting.FogEnd = 1e6
Lighting.GlobalShadows = false
Lighting.Ambient = Color3.fromRGB(178, 178, 178)
else
restore()
end
end,
})
visuals:Slider({
Name = "Field of View", Min = 40, Max = 120, Default = BASE_FOV, Step = 1,
Flag = "u_fov",
Callback = function(v)
