{ Label = "Load", Callback = load },
})
g:ButtonRow({
{ Label = "Delete", Callback = remove },
{ Label = "Refresh", Callback = refresh },
})
autoSwitch = g:Toggle({
Name = "Auto Load",
Desc = "Apply the selected config on launch.",
Default = window:GetAutoload() ~= nil,
