.. " — if you meant a title, write CreateTab({ Name = %s })")
:format(typeof(tabOpts), type(tabOpts) == "string" and ('"%s"'):format(tabOpts) or "..."))
end
Log.field("CreateTab", "Name", tabOpts and tabOpts.Name, "string")
