if type(name) == "table" then
for k, v in pairs(name) do opts[k] = v end
else
opts.Name = tostring(name or "Tab")
opts.Icon = icon
end
if type(extra) == "table" then
for k, v in pairs(extra) do opts[k] = v end
end
local key = tostring(opts.Name or "Tab")
opts.Name = key
local existing = self._tabs[key]
if existing then return existing:Set(opts) end
local final = self:_tabDefaults(key)
for k, v in pairs(opts) do final[k] = v end
final.Icon = final.Icon or "layers"
local wrapped = setmetatable({ Raw = self.Window:CreateTab(final), Name = key, Hub = self }, TabWrap)
self._tabs[key] = wrapped
return wrapped
end
function Hub:_tabDefaults(name)
local preset = TAB_PRESETS[name]
if preset then
local out = {}
for k, v in pairs(preset) do out[k] = v end
return out
end
if self._tabPhase == "game" then
self._gameTabs = self._gameTabs + 1
return {
Color = GAME_TAB_COLOR,
Dot = true,
Badge = "This game",
Desc = ("Only in %s."):format(shorten(self.PlaceName, 40)),
Order = ORDER.Game + self._gameTabs,
Separator = self._gameTabs == 1,
}
end
self._extraTabs = self._extraTabs + 1
return { Badge = "Global", Order = ORDER.Extra + self._extraTabs }
end
function Hub:Notify(text, kind, duration)
local opts = text
if type(opts) ~= "table" then
opts = { Title = self.Name, Text = tostring(text), Type = kind, Duration = duration }
end
self.Window:Notify(opts)
end
function Hub:Log(...)
log(...)
end
function Hub:Loop(interval, fn, opts)
assert(type(fn) == "function", "Hub:Loop(interval, fn) — fn must be a function")
opts = opts or {}
local t = setmetatable({
Name = opts.Name or "loop",
Interval = tonumber(interval) or 0,
Fn = fn,
OnStop = opts.OnStop,
OnFail = opts.OnFail,
Running = false,
_gen = 0,
_errors = 0,
}, Loop)
table.insert(self._tasks, t)
return t
end
function Hub:AutoToggle(surface, opts)
assert(type(surface) == "table", "Hub:AutoToggle(group, opts) — pass a Group or Section")
assert(type(opts) == "table" and type(opts.Run) == "function", "Hub:AutoToggle needs opts.Run")
local handle
local label = opts.Name or "Auto"
local loop = self:Loop(opts.Interval or 0.1, opts.Run, {
Name = label,
OnStop = opts.OnStop,
OnFail = function()
if handle and type(handle.Set) == "function" then
pcall(handle.Set, handle, false)
end
self:Notify(("%s stopped — it errored %d times in a row."):format(label, MAX_LOOP_ERRORS), "error")
end,
})
local keyed = CONFIG.Keybinds ~= false
or opts.Keybind ~= nil or opts.KeybindMode ~= nil or opts.KeybindFlag ~= nil
handle = surface:Toggle({
Name = label,
Desc = opts.Desc,
Default = opts.Default or false,
Flag = opts.Flag,
Keybind = opts.Keybind,
KeybindMode = keyed and (opts.KeybindMode or "Toggle") or nil,
KeybindModes = opts.KeybindModes,
KeybindFlag = keyed and (opts.KeybindFlag or (opts.Flag and opts.Flag .. "_key")) or nil,
Parent = opts.Parent,
Hud = opts.Hud,
Callback = function(on)
loop:Set(on)
if opts.Callback then opts.Callback(on) end
end,
})
if opts.Default then loop:Start() end
return handle, loop
end
function Hub:Bind(key, fn, mode)
if type(self.Window.Bind) ~= "function" then
warnLog("Hub:Bind needs a newer ui/uibundle.lua — binding skipped")
return nil
end
local binding = self.Window:Bind(key, fn, mode)
if binding then table.insert(self._binds, binding) end
return binding
end
function Hub:Connect(signal, fn)
local conn = signal:Connect(function(...)
local okRun, err = pcall(fn, ...)
if not okRun then warnLog("connection error:", err) end
end)
local list = self._connections
list[#list + 1] = conn
self._connAdds = self._connAdds + 1
if self._connAdds >= CONN_SWEEP_EVERY then
self._connAdds = 0
local kept = 0
for i = 1, #list do
local c = list[i]
if c.Connected ~= false then
kept = kept + 1
list[kept] = c
end
end
for i = #list, kept + 1, -1 do list[i] = nil end
end
return conn
end
function Hub:OnCharacter(fn)
local function run(char)
task.spawn(function()
local hum = char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 10)
local okRun, err = pcall(fn, char, hum)
if not okRun then warnLog("OnCharacter error:", err) end
end)
end
if self.Player.Character then run(self.Player.Character) end
return self:Connect(self.Player.CharacterAdded, run)
end
function Hub:OnUnload(fn)
table.insert(self._unloadFns, fn)
end
function Hub:OnReady(fn)
if self.Ready then
task.spawn(fn, self.Ready)
return
end
table.insert(self._readyFns, fn)
end
function Hub:_fireReady(info)
self.Ready = info
for _, fn in ipairs(self._readyFns) do
local okRun, err = pcall(fn, info)
if not okRun then warnLog("ready handler error:", err) end
end
self._readyFns = {}
end
function Hub:OnSettings(fn)
if self.SettingsTab then
local okRun, err = pcall(fn, self.SettingsTab)
if not okRun then warnLog("settings handler error:", err) end
return
end
table.insert(self._settingsFns, fn)
end
function Hub:_fireSettings(raw, controls)
local wrapped = setmetatable({
Raw = raw, Name = "Settings", Hub = self,
Controls = controls or raw.Controls,
}, TabWrap)
self.SettingsTab = wrapped
self._tabs["Settings"] = wrapped
for _, fn in ipairs(self._settingsFns) do
local okRun, err = pcall(fn, wrapped)
if not okRun then warnLog("settings handler error:", err) end
end
self._settingsFns = {}
end
function Hub:Char()
return self.Player.Character
end
local cachedChar, cachedRoot, cachedHum = nil, nil, nil
function Hub:Root()
local c = self.Player.Character
if c ~= cachedChar then cachedChar, cachedRoot, cachedHum = c, nil, nil end
if not c then return nil end
local root = cachedRoot
if root and root.Parent == c then return root end
root = c:FindFirstChild("HumanoidRootPart")
cachedRoot = root
return root
end
function Hub:Humanoid()
local c = self.Player.Character
if c ~= cachedChar then cachedChar, cachedRoot, cachedHum = c, nil, nil end
if not c then return nil end
local hum = cachedHum
if hum and hum.Parent == c then return hum end
hum = c:FindFirstChildOfClass("Humanoid")
cachedHum = hum
return hum
end
function Hub:Teleport(target)
local root = self:Root()
if not root then return false end
if typeof(target) == "Instance" then
target = target:IsA("BasePart") and target.CFrame or target:GetPivot()
elseif typeof(target) == "Vector3" then
target = CFrame.new(target)
end
if typeof(target) ~= "CFrame" then return false end
root.CFrame = target
return true
end
function Hub:Rejoin()
Configs:Flush()
if #Players:GetPlayers() <= 1 then
TeleportSvc:Teleport(PlaceId, self.Player)
else
TeleportSvc:TeleportToPlaceInstance(PlaceId, game.JobId, self.Player)
end
end
function Hub:ServerHop()
local url = ("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100"):format(PlaceId)
local okGet, body = pcall(function() return game:HttpGet(url) end)
if not okGet then
self:Notify("Couldn't reach the server list.", "error")
return false
end
local okDecode, data = pcall(function() return HttpService:JSONDecode(body) end)
if not okDecode or type(data) ~= "table" or type(data.data) ~= "table" then
self:Notify("Server list came back malformed.", "error")
return false
end
for _, server in ipairs(data.data) do
if server.playing and server.maxPlayers and server.playing < server.maxPlayers and server.id ~= game.JobId then
Configs:Flush()
TeleportSvc:TeleportToPlaceInstance(PlaceId, server.id, self.Player)
return true
end
end
self:Notify("No other server with room.", "warning")
return false
end
function Hub:Clipboard(text, label)
if type(setclipboard) ~= "function" then
self:Notify("No clipboard access on this executor.", "warning")
return false
end
setclipboard(tostring(text))
self:Notify(((label or "Value") .. " copied."), "success")
return true
end
function Hub:_cleanup()
if self._dead then return end
self._dead = true
for _, t in ipairs(self._tasks) do
pcall(t.Stop, t)
end
for _, c in ipairs(self._connections) do
pcall(c.Disconnect, c)
end
for _, b in ipairs(self._binds) do
pcall(b.Destroy, b)
end
for _, fn in ipairs(self._unloadFns) do
local okRun, err = pcall(fn)
if not okRun then warnLog("unload handler error:", err) end
end
debugLog("cleaned up")
end
function Hub:Reload()
local url = (EMBEDDED and EMBEDDED.url) or rawUrl(CONFIG.HubPath)
task.spawn(function()
local okRun, err = pcall(function()
loadstring(game:HttpGet(url, true))()
end)
if not okRun then warnLog("reload failed:", err) end
end)
end
function Hub:Unload()
self.Window:Destroy()
end
local SplashOpts = CONFIG.Splash
if SplashOpts == true then
SplashOpts = {
Subtitle = PlaceName,
Steps = { "Loading scripts…", "Building interface…", "Ready" },
}
end
local Window = Uranium:CreateWindow({
Title = "Uranium",
Subtitle = PlaceName,
Version = "v1.0.0",
Splash = SplashOpts,
Logo = { Uranium.Asset.url("uranium-orbitals-512-square.png") },
ConfigFolder = PLACE_FOLDER,
ToggleKey = Enum.KeyCode.RightShift,
Keybinds = CONFIG.Keybinds,
Hud = CONFIG.Hud,
Parent = guiParent(),
OnFlag = function(name) flagScope[name] = flagPhase end,
})
do
local gui = Window.ScreenGui
if typeof(gui) ~= "Instance" then
local env = (type(getgenv) == "function") and getgenv() or nil
local record = env and env._URANIUM_LOADED
gui = type(record) == "table" and record.ScreenGui or nil
end
if typeof(gui) == "Instance" then
hideGui(gui)
else
debugLog("no ScreenGui handle — window left where the library parented it")
end
end
local hub = Hub.new(Window)
hub.Configs = Configs
Configs:Attach(hub)
do
local originalDestroy = Window.Destroy
Window.Destroy = function(self, ...)
hub:_cleanup()
return originalDestroy(self, ...)
end
end
do
local save, delete = Window.SaveConfig, Window.DeleteConfig
Configs:Loader(Window.LoadConfig)
function Window:SaveConfig(name, meta)
return save(self, name, Configs:Meta(meta))
end
function Window:LoadConfig(display)
local entry = Configs:Resolve(display)
local owner = Configs:Owner(entry)
if owner then
hub:Notify(('"%s" belongs to %s. Import it to use it here.'):format(entry.name, owner), "warning")
return false, "handled"
end
return Configs:LoadGame(entry)
end
function Window:DeleteConfig(display)
local entry = Configs:Resolve(display)
if entry.own then return delete(self, entry.name) end
return Uranium.Config.delete(entry.folder, entry.name)
end
function Window:ListConfigs()
return Configs:Refresh()
end
end
if CONFIG.Defaults then
local defaults, err = hub:Run(CONFIG.DefaultsPath)
if not defaults then
warnLog(("default scripts didn't load (%s) — the hub will be empty"):format(tostring(err)))
end
end
local placePath = tostring(PlaceId)
hub._tabPhase, flagPhase = "game", "game"
local placeScript, placeSource = hub:Run(placePath)
hub._tabPhase, flagPhase = "hub", "hub"
Configs:SnapshotDefaults(Window)
if placeScript then
log(("ran %s (%s)"):format(placeScript.Name or placePath, tostring(placeSource)))
hub:Notify(("Loaded %s."):format(placeScript.Name or "script"), "success")
elseif not RUN_FAILURES[placeSource] then
log(("no script for this place (looked for %s/%s/init.lua — %s)"):format(
CONFIG.ScriptsPath, placePath, tostring(placeSource)))
hub:Notify("No script for this place — default tools only.", "info")
else
warnLog(("%s/%s/init.lua failed to load (%s) — its warning is above"):format(
CONFIG.ScriptsPath, placePath, tostring(placeSource)))
hub:Notify("This game's script failed to load — see the console.", "error")
end
hub:_fireReady({
Loaded = placeScript ~= nil,
Script = placeScript,
Source = placeSource,
Path = ("%s/%s/init.lua"):format(CONFIG.ScriptsPath, placePath),
})
local settingsTab, settingsControls = Window:CreateSettingsTab(TAB_PRESETS.Settings)
hub:_fireSettings(settingsTab, settingsControls)
hub._tabPhase, flagPhase = "game", "game"
Configs:ApplyShared()
Configs:StartSync()
return hub
